// === DETECTAR TIPO DE EVENTO ===

const body = $json.body;

// Log completo do payload
console.log('[DETECT] Full body:', JSON.stringify(body, null, 2));
console.log('[DETECT] Event:', body.event || 'message.received');

// 1. Evento de TRANSCRIÇÃO (plugin voice-transcription)
if (body.event === 'message.transcription') {
  const transcription = body.transcription || {};

  console.log('[DETECT] Transcription event detected');
  console.log('[DETECT] Status:', body.status);
  console.log('[DETECT] Transcription text:', transcription.text);

  // Se transcrição falhou ou está vazia
  if (body.status !== 'completed' || !transcription.text || transcription.text.trim() === '') {
    console.log('[DETECT] Skipping transcription - status:', body.status, 'text empty:', !transcription.text);
    return {
      json: {
        route: 'skip',
        reason: `Transcrição ${body.status} ou vazia`,
        chatId: body.chatId,
        messageId: body.messageId
      }
    };
  }

  // Transcrição OK → Processar como áudio
  console.log('[DETECT] ✅ Route: audio_transcription');
  return {
    json: {
      route: 'audio_transcription',
      chatId: body.chatId,
      messageId: body.messageId,
      text: transcription.text,
      language: transcription.language || 'pt',
      provider: transcription.provider || 'groq',
      isAudio: true,
      timestamp: new Date().toISOString()
    }
  };
}

// 2. Mensagem normal (message.received)
const data = body.data || {};
const messageType = data.type || 'text';
const messageBody = data.body || '';

console.log('[DETECT] Message type:', messageType);
console.log('[DETECT] Message body:', messageBody);
console.log('[DETECT] ChatId:', data.chatId);

// Se for ÁUDIO → Ignorar (aguardar transcrição)
if (messageType === 'voice' || messageType === 'audio' || messageType === 'ptt') {
  console.log('[DETECT] ⏸️ Voice message detected, SKIP (waiting for transcription)');
  return {
    json: {
      route: 'skip',
      reason: 'Aguardando transcrição de áudio',
      chatId: data.chatId,
      messageId: data.id
    }
  };
}

// Se for TEXTO → Processar
if (messageType === 'text' || messageType === 'chat') {
  console.log('[DETECT] ✅ Route: text_message');
  return {
    json: {
      route: 'text_message',
      chatId: data.chatId,
      messageId: data.id,
      from: data.from,
      text: messageBody,
      isAudio: false,
      timestamp: new Date().toISOString()
    }
  };
}

// Outros tipos → Ignorar
console.log('[DETECT] ⏸️ Unsupported type:', messageType);
return {
  json: {
    route: 'skip',
    reason: `Tipo não suportado: ${messageType}`,
    chatId: data.chatId,
    messageId: data.id
  }
};

// === NORMALIZAR MENSAGEM DE TEXTO ===

const data = $input.first().json;
const messageBody = data.text || '';

// Normalizar texto (remover acentos)
const normalize = (text) => {
  return text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
};

const normalized = normalize(messageBody);

// === DETECTAR TIPO DE SOLICITAÇÃO ===
let tipo = 'geral';
let urgencia = false;
let categoria = null;

// Previdenciário
if (normalized.match(/auxilio|beneficio|inss|doenca|afastado|incapacitado|pericia/)) {
  tipo = 'previdenciario';
  if (normalized.match(/auxilio|beneficio/)) categoria = 'auxilio-doenca';
  if (normalized.match(/aposentadoria|invalidez/)) categoria = 'aposentadoria';
  if (normalized.match(/pericia|laudo/)) categoria = 'pericia';
}

// Família
if (normalized.match(/divorcio|separacao|separar|casal|marido|esposa/)) {
  tipo = 'familia';
  if (normalized.match(/divorcio|separacao/)) categoria = 'divorcio';
  if (normalized.match(/bens|casa|carro|dividir|partilha/)) categoria = 'divisao-bens';
  if (normalized.match(/pensao|alimentos/)) categoria = 'pensao';
}

// Acompanhamento
if (normalized.match(/processo|andamento|resultado|como esta|liberado|disponivel/)) {
  tipo = 'acompanhamento';
  categoria = 'status-processo';
}

// Urgência
if (normalized.match(/urgente|remedio|cirurgia|preciso|dinheiro|conta|pagar/)) {
  urgencia = true;
}

// CPF?
let precisaCPF = false;
if (tipo === 'acompanhamento' && !normalized.match(/\d{11}|\d{3}\.\d{3}\.\d{3}-\d{2}/)) {
  precisaCPF = true;
}

return {
  json: {
    messageOriginal: messageBody,
    chatId: data.chatId,
    from: data.from,
    messageId: data.messageId,
    messageNormalized: normalized,
    tipo: tipo,
    categoria: categoria,
    urgencia: urgencia,
    precisaCPF: precisaCPF,
    isAudio: false,
    timestamp: data.timestamp
  }
};

// === NORMALIZAR TRANSCRIÇÃO DE ÁUDIO ===

const data = $input.first().json;
const messageBody = data.text || '';

// Normalizar texto
const normalize = (text) => {
  return text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
};

const normalized = normalize(messageBody);

// Detecção simplificada (áudio costuma ser mais curto)
let tipo = 'geral';
let urgencia = false;

if (normalized.match(/urgente|remedio|cirurgia|preciso/)) {
  urgencia = true;
}

if (normalized.match(/processo|andamento|como esta/)) {
  tipo = 'acompanhamento';
}

return {
  json: {
    messageOriginal: messageBody,
    chatId: data.chatId,
    messageId: data.messageId,
    messageNormalized: normalized,
    tipo: tipo,
    urgencia: urgencia,
    isAudio: true,
    language: data.language,
    provider: data.provider,
    timestamp: data.timestamp
  }
};

// === MONTAR PROMPT INTELIGENTE ===

const data = $input.first().json;
const isAudio = data.isAudio || false;

// System Prompt BASE
let systemPrompt = `Você é assistente virtual do escritório Dr. Dênis Bernardo, especializado em direito previdenciário e de família.

🎯 MISSÃO:
Fazer triagem inicial, identificar necessidades e coletar dados básicos.

💬 REGRAS:
1. TOM: Informal mas respeitoso, como vizinho de confiança
2. LINGUAGEM: Português simples, sem juridiquês. Máximo 2-3 frases
3. ERROS DO CLIENTE: Entenda contexto, não corrija português
4. NUNCA invente status de processo ou prometa resultado

Se não souber: "Vou anotar e o Dr. Denis te responde."

SEMPRE termine: "Precisa de mais alguma coisa?"`;

// Se veio de ÁUDIO, adicionar contexto especial
if (isAudio) {
  systemPrompt += `\n\n⚠️ IMPORTANTE: Esta mensagem veio de um ÁUDIO (não foi digitada).\n- Cliente usou voz, responda de forma natural e conversacional\n- Confirme que entendeu: "Ouvi seu áudio! Você disse [resumo]. Tá certo?"`;
}

// === CONTEXTO ADICIONAL ===
let contextoAdicional = '';

if (data.urgencia) {
  contextoAdicional += '\n\n⚠️ URGÊNCIA DETECTADA! Priorize empatia.\nResponda: "Entendo que é urgente. Vou priorizar seu atendimento."';
}

if (data.tipo === 'acompanhamento' && data.precisaCPF) {
  contextoAdicional += '\n\n📋 Cliente quer status mas não informou CPF. Peça: "Pra eu consultar certinho, qual seu CPF?"';
}

// === USER PROMPT ===
let userPrompt = '';

if (isAudio) {
  userPrompt = `🎤 ÁUDIO TRANSCRITO (${data.language}):\n"${data.messageOriginal}"\n\nProvider: ${data.provider}${contextoAdicional}\n\nResponda confirmando que ouviu o áudio e ajude o cliente.`;
} else {
  userPrompt = `${contextoAdicional}\n\nTIPO: ${data.tipo}\nCATEGORIA: ${data.categoria || 'não identificada'}\n\nMENSAGEM:\n"${data.messageOriginal}"\n\nResponda de forma clara e curta (2-3 frases).`;
}

return {
  json: {
    systemPrompt: systemPrompt,
    userPrompt: userPrompt,
    chatId: data.chatId,
    messageId: data.messageId,
    tipo: data.tipo,
    urgencia: data.urgencia,
    isAudio: isAudio
  }
};

// === LIMPAR RESPOSTA ===

// Pegar texto do LLM
const llmOutput = $input.first().json;
let text = llmOutput.text || llmOutput.output || '';

// Log antes de limpar
console.log('[CLEAN] Raw LLM output length:', text.length);
console.log('[CLEAN] First 100 chars:', text.substring(0, 100));

// Remover tags <think>...</think>
const originalLength = text.length;
text = text.replace(/<think>[\s\S]*?<\/think>/g, '');
const cleanedLength = text.length;

if (originalLength !== cleanedLength) {
  console.log('[CLEAN] Removed', originalLength - cleanedLength, 'chars of <think> tags');
}

// Trim espaços
text = text.trim();

// Se ficou vazio, usar fallback
if (!text || text.length === 0) {
  console.error('[CLEAN] ERROR: Text is empty after cleaning!');
  text = 'Desculpa, tive um problema ao processar. Pode repetir?';
}

// Pegar dados do node "2. Montar Prompt"
// Usar $('2. Montar Prompt').first().json ao invés de $item
const promptData = $('2. Montar Prompt').first().json;

if (!promptData) {
  console.error('[CLEAN] ERROR: Could not get data from "2. Montar Prompt" node');
  throw new Error('Node "2. Montar Prompt" data not found');
}

console.log('[CLEAN] Final text length:', text.length);
console.log('[CLEAN] Final text:', text);

return {
  json: {
    chatId: promptData.chatId,
    text: text,
    messageId: promptData.messageId,
    isAudio: promptData.isAudio
  }
};
